import React, { forwardRef } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";

import { ButtonGroupProps } from "./button-group.types";
import { ButtonGroupClasses, StyledButtonGroup } from "./button-group.styles";

const ButtonGroup = forwardRef(
  (
    { className, variant = "default", children, ...props }: ButtonGroupProps,
    ref: React.ForwardedRef<HTMLDivElement>,
  ) => {
    const theme = useTheme();
    const rootClasses = clsx(ButtonGroupClasses.root, className);

    return (
      <StyledButtonGroup
        ref={ref}
        className={rootClasses}
        currentTheme={theme}
        role="group"
        variant={variant}
        {...props}
      >
        {children}
      </StyledButtonGroup>
    );
  },
);

ButtonGroup.displayName = "ButtonGroup";

export default ButtonGroup;
